const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
  const nums = (await readline()).split(" ").map(Number);
  console.log(getResult(nums));
})();

function getResult(nums) {
  const ans = [];

  // 上一个点坐标（preX, preY）
  let preX = nums[0];
  let preY = nums[1];

  // 上一次的运动方向（preDirectX, preDirectY）
  let preDirectX = 0;
  let preDirectY = 0;

  for (let i = 2; i < nums.length; i += 2) {
    // 当前点坐标（curX, curY）
    const curX = nums[i];
    const curY = nums[i + 1];

    // 上一个点到当前点的偏移量（offsetX, offsetY）
    const offsetX = curX - preX;
    const offsetY = curY - preY;

    // 根据偏移量得出本次的运动方向
    const base = Math.max(Math.abs(offsetX), Math.abs(offsetY));
    const directX = offsetX / base;
    const directY = offsetY / base;

    // 如果两次运动的方向不同
    if (directX != preDirectX || directY != preDirectY) {
      // 则上一个点是拐点，需要记录下来
      ans.push(preX, preY);
    }

    preX = curX;
    preY = curY;

    preDirectX = directX;
    preDirectY = directY;
  }

  // 注意收尾
  ans.push(preX, preY);

  return ans.join(" ");
}

